    "command": "cd packages/spec/src/system && grep -hoE '^\\s+[A-Za-z][A-Za-z0-9]*: retiredKey\\(' incident-response.zod.ts training.zod.ts change-management.zod.ts | sed -E 's/^\\s+//; s/: retiredKey\\($//'  then wc -l / sort -u | wc -l / sort | uniq -d",
